package pl.forma.todo;
import android.app.*;import android.os.*;import android.webkit.*;import android.content.*;import android.content.pm.PackageManager;import android.database.Cursor;import android.provider.CalendarContract;import android.net.Uri;import org.json.*;
public class MainActivity extends Activity {
 WebView w;
 public void onCreate(Bundle b){super.onCreate(b);w=new WebView(this);w.setBackgroundColor(0xfff3f1ec);if(Build.VERSION.SDK_INT>=35)w.setOnApplyWindowInsetsListener((v,i)->{android.graphics.Insets s=i.getInsets(android.view.WindowInsets.Type.systemBars());v.setPadding(s.left,s.top,s.right,s.bottom);return i;});setContentView(w);w.getSettings().setJavaScriptEnabled(true);w.getSettings().setDomStorageEnabled(true);w.addJavascriptInterface(new Bridge(),"Native");w.loadUrl("file:///android_asset/index.html");}
 class Bridge {
 @JavascriptInterface public String load(){return getSharedPreferences("data",0).getString("state","");}
 @JavascriptInterface public void save(String s){getSharedPreferences("data",0).edit().putString("state",s).apply();}
 @JavascriptInterface public void permissions(){runOnUiThread(()->{if(Build.VERSION.SDK_INT>=33&&checkSelfPermission("android.permission.POST_NOTIFICATIONS")!=PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{"android.permission.POST_NOTIFICATIONS"},1);else if(Build.VERSION.SDK_INT>=31&&!getSystemService(AlarmManager.class).canScheduleExactAlarms())startActivity(new Intent(android.provider.Settings.ACTION_REQUEST_SCHEDULE_EXACT_ALARM,Uri.parse("package:"+getPackageName())));});}
 @JavascriptInterface public String schedule(String id,String title,long time){Reminder.cancel(MainActivity.this,id);if(time<=System.currentTimeMillis())return "Termin przypomnienia minął";Reminder.set(MainActivity.this,id,title,time);return Build.VERSION.SDK_INT>=31&&!getSystemService(AlarmManager.class).canScheduleExactAlarms()?"Zapisano alarm przybliżony. Włącz dokładne alarmy w ustawieniach.":"Zapisano przypomnienie";}
 @JavascriptInterface public void cancel(String id){Reminder.cancel(MainActivity.this,id);}
 @JavascriptInterface public String calendars(){if(checkSelfPermission("android.permission.READ_CALENDAR")!=0||checkSelfPermission("android.permission.WRITE_CALENDAR")!=0){runOnUiThread(()->requestPermissions(new String[]{"android.permission.READ_CALENDAR","android.permission.WRITE_CALENDAR"},2));return "[]";}JSONArray a=new JSONArray();try(Cursor c=getContentResolver().query(CalendarContract.Calendars.CONTENT_URI,new String[]{"_id","calendar_displayName","account_name"},"calendar_access_level>=500 AND visible=1",null,null)){while(c!=null&&c.moveToNext()){JSONObject o=new JSONObject();o.put("id",c.getLong(0));o.put("name",c.getString(1)+" · "+c.getString(2));a.put(o);}}catch(Exception e){}return a.toString();}
 @JavascriptInterface public String event(String old,String cal,String title,long start,String desc){try{ContentValues v=new ContentValues();v.put("calendar_id",Long.parseLong(cal));v.put("title",title);v.put("description",desc);v.put("dtstart",start);v.put("dtend",start+86400000L);v.put("allDay",1);v.put("eventTimezone","UTC");if(!old.isEmpty()){int n=getContentResolver().update(ContentUris.withAppendedId(CalendarContract.Events.CONTENT_URI,Long.parseLong(old)),v,null,null);if(n>0)return old;}Uri u=getContentResolver().insert(CalendarContract.Events.CONTENT_URI,v);return u==null?"":u.getLastPathSegment();}catch(Exception e){return "";}}
 @JavascriptInterface public boolean removeEvent(String id){try{getContentResolver().delete(ContentUris.withAppendedId(CalendarContract.Events.CONTENT_URI,Long.parseLong(id)),null,null);return true;}catch(Exception e){return false;}}
 }
}
